def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find the full row or column of color 2.
    stripe = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            stripe = ("row", r)
            break
    if stripe is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                stripe = ("col", c)
                break
    if stripe is None:
        return out

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    if not cells:
        return out

    axis, pos = stripe
    if axis == "col":
        left, right = min(c for r, c in cells), max(c for r, c in cells)
        if right < pos:
            dc = pos - 1 - right
        elif left > pos:
            dc = pos + 1 - left
        else:
            dc = 0
        moved = [(r, c + dc) for r, c in cells]
        for r, c in cells:
            out[r][c] = bg
        for r, c in moved:
            out[r][c] = grid[r][c - dc]
        edge = min(c for r, c in moved) - 1 if max(c for r, c in moved) < pos else max(c for r, c in moved) + 1
        if 0 <= edge < w:
            for r in range(h):
                out[r][edge] = 8
    else:
        top, bottom = min(r for r, c in cells), max(r for r, c in cells)
        if bottom < pos:
            dr = pos - 1 - bottom
        elif top > pos:
            dr = pos + 1 - top
        else:
            dr = 0
        moved = [(r + dr, c) for r, c in cells]
        for r, c in cells:
            out[r][c] = bg
        for r, c in moved:
            out[r][c] = grid[r - dr][c]
        edge = min(r for r, c in moved) - 1 if max(r for r, c in moved) < pos else max(r for r, c in moved) + 1
        if 0 <= edge < h:
            for c in range(w):
                out[edge][c] = 8

    return out
